"""The envelopes the platform POSTs to a function, built as the API builds
them.

A function is called with ``{"context": ..., "payload": ...}`` in one of
three shapes, one per path in the API:

``row_save``
    A row saved through the Tables API, before (``pre_save``) or after
    (``post_save``) it is written. The context describes the table, the
    person who saved and the row; the payload is the row's ``data``.
``agent_write``
    A row Workpeg AI wrote with its own table tools. Flatter: the table's
    uuid, the business and ``actor: "agent"``.
``phase_action``
    A manifest action with a ``phase``: its name, the table, the phase, the
    business, and the model's arguments as the payload.

Each shape ends with ``business`` and ``token``, the one-call credential a
function writes back with (``docs/tables.md``). ``workpeg function test``
builds them with :data:`TEST_TOKEN`, which the platform refuses, so a test
reaches nothing.

They are held to ``tests/fixtures/function_envelopes.json``, the SDK's copy of
the API's own record of what it sends, key for key and in order. These are
not the API's validator (``workpeg.context.ContextBuilder``): they build what
it built, they do not check it.
"""
from __future__ import annotations

from typing import Any

__all__ = ["TEST_BUSINESS", "TEST_ROW", "TEST_TABLE", "TEST_TOKEN",
           "agent_write", "offline_envelope", "phase_action", "row_save"]

#: The token ``workpeg function test`` hands a function. Not a JWT, so the
#: API refuses it on every route: a test writes nothing anywhere.
TEST_TOKEN = "test-token"

#: The business, table and row ids ``workpeg function test`` uses. Fixed, so
#: that two runs of a test see the same envelope.
TEST_BUSINESS = "00000000-0000-4000-8000-000000000001"
TEST_TABLE = "00000000-0000-4000-8000-000000000002"
TEST_ROW = "00000000-0000-4000-8000-000000000003"


def row_save(*, table: "dict | None", staff: "dict | None",
             row: "dict | None", metadata: Any, data: dict, business: str,
             token: str) -> dict:
    """A Tables API save. *row* is ``{"id": ...}`` once the row exists, and
    ``None`` for a pre-save of a new one; *metadata* is the row's own
    metadata, ``None`` until it exists. The payload is *data* in both
    phases: the incoming fields before a save, the saved fields after."""
    return {
        "context": {
            "table": table,
            "staff": staff,
            "row": row,
            "metadata": metadata,
            "business": business,
            "token": token,
        },
        "payload": data,
    }


def agent_write(*, table: str, business: str, data: dict,
                token: str) -> dict:
    """A row Workpeg AI wrote. *table* is the table's uuid, not an object."""
    return {
        "context": {
            "table": table,
            "business": business,
            "actor": "agent",
            "token": token,
        },
        "payload": data,
    }


def phase_action(*, action: str, table: str, phase: str, business: str,
                 args: Any, token: str) -> dict:
    """A manifest action with a phase. Arguments that are not an object
    reach the function as ``{}``, as the API sends them."""
    return {
        "context": {
            "action": action,
            "table": table,
            "phase": phase,
            "business": business,
            "token": token,
        },
        "payload": args if isinstance(args, dict) else {},
    }


def offline_envelope(kind: str, *, phase: str, namespace: str,
                     payload: dict, action: "str | None" = None) -> dict:
    """The envelope ``workpeg function test`` sends: shape *kind* (``row``,
    ``agent`` or ``action``) with the test ids and :data:`TEST_TOKEN`."""
    if kind == "row":
        saved = phase == "post_save"
        return row_save(
            table={
                "uuid": TEST_TABLE,
                "name": "test",
                "owner_id": None,
                "metadata": {},
                "columns": [],
                "namespace": namespace,
                "peg": None,
            },
            staff={"first_name": "Test", "last_name": "Person",
                   "email": "test@example.com"},
            row={"id": TEST_ROW} if saved else None,
            metadata={} if saved else None,
            data=payload, business=TEST_BUSINESS, token=TEST_TOKEN)
    if kind == "agent":
        return agent_write(table=TEST_TABLE, business=TEST_BUSINESS,
                           data=payload, token=TEST_TOKEN)
    if kind == "action":
        if not action:
            raise ValueError("an action envelope needs --action NAME")
        return phase_action(action=action, table=TEST_TABLE, phase=phase,
                            business=TEST_BUSINESS, args=payload,
                            token=TEST_TOKEN)
    raise ValueError(f"no envelope {kind!r}")
